WITH unpacked AS (SELECT id, created_at, attributes, ARRAY_MAX(TRANSFORM(items, item -> item.price)) AS max_item_price, ship_to.country AS ship_country, SIZE(FILTER(items, item -> item.qty >= 3)) AS bulk_lines, EXISTS(items, item -> item.price > 100) AS has_premium_item, COALESCE(attributes['device'], 'direct') AS device_or_default FROM carts) SELECT *, AVG(bulk_lines) OVER (PARTITION BY ship_country) AS ship_country_avg_bulk_lines, NTILE(5) OVER (PARTITION BY ship_country ORDER BY bulk_lines DESC, id) AS bulk_lines_bucket, LAST_VALUE(bulk_lines) IGNORE NULLS OVER (ORDER BY bulk_lines, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_bulk_lines, ROW_NUMBER() OVER (PARTITION BY ship_country ORDER BY bulk_lines, id) AS seq_no, SUM(bulk_lines) OVER (PARTITION BY ship_country ORDER BY bulk_lines, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_bulk_lines FROM unpacked;
